using System.Text;using System.Text.Json;using UnifiedMediaHub.Core;using Xunit;
namespace UnifiedMediaHub.Tests;
public sealed class BridgeImportTests
{
 [Fact]public void ExplicitOversizedMarkersAreAcceptedButAmbiguousEntriesAreRejected(){const string body="""{"bridgeVersion":"1","platform":"douyin","listKind":"saved","page":{"path":"/user/self","tab":"favorite_collection"},"items":[{"hrefId":"123","oversized":true}]}""";Assert.Equal(1,BridgePayload.Parse(Encoding.UTF8.GetBytes(body)).Count);foreach(var text in new[]{body.Replace("true","false"),body.Replace("\"oversized\":true","\"oversized\":true,\"aweme\":{}"),body.Replace("true","\"true\"")})Assert.ThrowsAny<Exception>(()=>BridgePayload.Parse(Encoding.UTF8.GetBytes(text)));}
 [Fact]public async Task Large165AssetBridgeEventCrossesActualOwnedWorkerPipe(){var project=new DirectoryInfo(AppContext.BaseDirectory);while(project!=null&&!File.Exists(Path.Combine(project.FullName,"AGENTS.md")))project=project.Parent;var codeRoot=project!.FullName;var root=Path.Combine(Path.GetTempPath(),"umh-bridge-165-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{var raw=JsonSerializer.SerializeToElement(new{bridgeVersion="1",platform="douyin",listKind="saved",page=new{path="/user/self",tab="favorite_collection"},items=new[]{new{hrefId="123",aweme=new{awemeId="123",images=Enumerable.Range(0,93).Select(i=>new{urlList=new[]{"https://p3.douyinpic.com/"+i+new string('x',650)+".webp"},video=i<72?new{playAddr=new[]{"https://v1.zjcdn.com/"+i+new string('y',650)+".mp4"}}:null})}}}});var payload=BridgePayload.Parse(Encoding.UTF8.GetBytes(raw.GetRawText()));var options=new UnifiedMediaHub.Core.Runtime.WorkerLaunchOptions{ExecutablePath=Path.Combine(codeRoot,"runtime/node/node.exe"),WorkerScriptPath=Path.Combine(codeRoot,"tests/fixtures/bridge-entry.mjs"),WorkingDirectory=codeRoot,Environment=new(){["TEMP"]=root,["TMP"]=root}};await using var session=await UnifiedMediaHub.Core.Runtime.OwnedWorkerSession.StartAsync(options,new(){RequestId="bridge-large",Operation="importBridge",Source=BridgeImports.Source(payload,null),BridgePayload=payload.Value,Paths=new(){DataRoot=root,DownloadRoot=root,BrowserExecutable=options.ExecutablePath,EngineRoot=root}});using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(15));var rows=new List<WorkerEvent>();await foreach(var e in session.ReadEventsAsync(timeout.Token))rows.Add(e);await session.Completion;var item=Assert.Single(rows,e=>e.Type=="item").Item!;Assert.True(item.MediaResolved);Assert.Equal(165,item.Media.Count);Assert.Equal("completed",rows[^1].Status);}finally{Directory.Delete(root,true);}}
 [Theory][InlineData(1)][InlineData(200)]public async Task UnresolvedWorkCannotBlockLaterHostBatchesAndCountIsVisible(int batchSize){var root=Path.Combine(Path.GetTempPath(),"umh-bridge-skip-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{using var repo=new HubRepository(Path.Combine(root,"hub.db"));repo.Initialize();var job=repo.CreateJob(BridgeImports.Source(BridgePayload.Parse(Payload(3)),null),root);repo.UpsertItems(job.Id,Enumerable.Range(1,3).Select(i=>new ContentItem{Platform="douyin",ContentId=i.ToString(),SourceUrl="https://www.douyin.com/video/"+i,MediaResolved=i!=2,Media=i==2?[]:[new(){Index=1,Kind="image",Url="https://p3.douyinpic.com/synthetic.png"}]}));var received=new List<string>();var runner=new FixtureRunner(async(request,emit,_ct)=>{foreach(var item in request.Items!){Assert.True(item.MediaResolved);received.Add(item.ContentId);var file=Path.Combine(root,item.ContentId+".png");byte[] bytes=[1,2,3];File.WriteAllBytes(file,bytes);await emit(new(){Type="receipt",Receipt=new(){ContentKey=item.Key,MediaIndex=1,FilePath=file,Bytes=bytes.Length,Sha256=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(bytes)),Status="completed"}});}await emit(new(){Type="complete",Status="completed",Completeness="partial"});});await using var hub=new HubCoordinator(repo,runner,new(){DataRoot=root,DownloadRoot=root},batchSize);hub.Enable();await hub.Submit(job.Id,"download");Assert.Equal(new[]{"1","3"},received);Assert.Equal(2,repo.ListReceipts(job.Id).Count);Assert.Equal("needs_action",repo.GetJob(job.Id)!.Status);Assert.Equal("bridge_refresh_required",repo.GetJob(job.Id)!.ReasonCode);Assert.Contains("跳过 1",repo.GetJob(job.Id)!.Message);}finally{Directory.Delete(root,true);}}
 [Theory][InlineData(true)][InlineData(false)]public void BridgeSnapshotCannotInheritStaleMediaFromAnotherJob(bool resolved){var root=Path.Combine(Path.GetTempPath(),"umh-bridge-snapshot-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{using var repo=new HubRepository(Path.Combine(root,"hub.db"));repo.Initialize();var old=repo.CreateJob(new(){Platform="douyin",Kind="profile",Url="https://www.douyin.com/user/synthetic"},root);repo.UpsertItems(old.Id,[new(){Platform="douyin",ContentId="1",MediaResolved=true,Media=[new(){Index=1,Kind="image",Url="https://p3.douyinpic.com/old1"},new(){Index=2,Kind="image",Url="https://p3.douyinpic.com/old2"}]}]);var bridge=repo.CreateJob(BridgeImports.Source(BridgePayload.Parse(Payload()),null),root);repo.UpsertItems(bridge.Id,[new(){Platform="douyin",ContentId="1",MediaResolved=resolved,Media=resolved?[new(){Index=1,Kind="image",Url="https://p3.douyinpic.com/fresh"}]:[]}]);var item=Assert.Single(repo.ListItems(bridge.Id));Assert.Equal(resolved,item.MediaResolved);Assert.Equal(resolved?1:0,item.Media.Count);Assert.Equal(2,Assert.Single(repo.ListItems(old.Id)).Media.Count);}finally{Directory.Delete(root,true);}}
 [Fact]public void AccountReviewConfirmationIsScopedToCurrentBoundAccount(){var root=Path.Combine(Path.GetTempPath(),"umh-bridge-review-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{using var repo=new HubRepository(Path.Combine(root,"hub.db"));repo.Initialize();var source=BridgeImports.Source(BridgePayload.Parse(Payload()),"bound-a");var job=repo.CreateJob(source,root);repo.ConfirmBridge(job.Id);Assert.True(repo.GetJob(job.Id)!.Source.Bridge!.Confirmed);repo.ReviewBridgeAccount(job.Id,"bound-b");Assert.False(repo.GetJob(job.Id)!.Source.Bridge!.Confirmed);Assert.True(repo.GetJob(job.Id)!.Source.Bridge!.ConfirmationRequired);repo.ReviewBridgeAccount(job.Id,"synthetic-viewer");Assert.False(repo.GetJob(job.Id)!.Source.Bridge!.ConfirmationRequired);}finally{Directory.Delete(root,true);}}
 [Fact]public async Task LargeBridgePayloadFitsActualOwnedWorkerWithoutBrowserOrHtmlEscapingExpansion(){
  var project=new DirectoryInfo(AppContext.BaseDirectory);while(project!=null&&!File.Exists(Path.Combine(project.FullName,"AGENTS.md")))project=project.Parent;var codeRoot=project!.FullName;var root=Path.Combine(Path.GetTempPath(),"umh-bridge-wire-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
  try{var raw=JsonSerializer.SerializeToElement(new{bridgeVersion="1",platform="douyin",listKind="liked",page=new{path="/user/self",tab="like"},items=Enumerable.Range(1,20).Select(i=>new{hrefId=i.ToString(),aweme=new{awemeId=i.ToString(),desc=new string('<',180000),video=new{playAddr=new[]{"https://v1.zjcdn.com/synthetic.mp4"}}}})},new JsonSerializerOptions{Encoder=System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping});var payload=BridgePayload.Parse(Encoding.UTF8.GetBytes(raw.GetRawText()));var options=new UnifiedMediaHub.Core.Runtime.WorkerLaunchOptions{ExecutablePath=Path.Combine(codeRoot,"runtime/node/node.exe"),WorkerScriptPath=Path.Combine(codeRoot,"tests/fixtures/bridge-entry.mjs"),WorkingDirectory=codeRoot,Environment=new(){["TEMP"]=root,["TMP"]=root}};var request=new WorkerRequest{RequestId="bridge-wire",Operation="importBridge",Source=BridgeImports.Source(payload,null),BridgePayload=payload.Value,Paths=new(){DataRoot=root,DownloadRoot=root,BrowserExecutable=options.ExecutablePath,EngineRoot=root}};await using var session=await UnifiedMediaHub.Core.Runtime.OwnedWorkerSession.StartAsync(options,request);using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(15));var rows=new List<WorkerEvent>();await foreach(var row in session.ReadEventsAsync(timeout.Token))rows.Add(row);await session.Completion;Assert.Equal(20,rows.Count(e=>e.Type=="item"));Assert.Equal("bridge_snapshot",rows[^1].ReasonCode);Assert.Equal("completed",rows[^1].Status);}finally{Directory.Delete(root,true);}
 }
 static byte[] Payload(int count=1,string viewer="synthetic-viewer")=>Encoding.UTF8.GetBytes(JsonSerializer.Serialize(new{bridgeVersion="1",platform="douyin",listKind="liked",page=new{path="/user/self",tab="like"},viewer=new{secUid=viewer,nickname="Synthetic viewer"},items=Enumerable.Range(1,count).Select(i=>new{hrefId=i.ToString(),aweme=new{awemeId=i.ToString()}})}));
 [Fact]public void PayloadRejectsBoundsDuplicateKeysAndUntrustedApproval(){Assert.Throws<InvalidDataException>(()=>BridgePayload.Parse(Payload(1001)));foreach(var text in new[]{"{}",Encoding.UTF8.GetString(Payload()).Replace("\"bridgeVersion\":\"1\"","\"bridgeVersion\":\"1\",\"bridgeVersion\":\"1\""),Encoding.UTF8.GetString(Payload()).Replace("\"items\":","\"approved\":true,\"items\":")})Assert.ThrowsAny<Exception>(()=>BridgePayload.Parse(Encoding.UTF8.GetBytes(text)));var p=BridgePayload.Parse(Payload());Assert.Equal(1,p.Count);Assert.Equal("synthetic-viewer",p.ViewerId);}
 [Fact]public async Task ImportCreatesSnapshotTaskAndMismatchNeedsLocalConfirmation(){var root=Path.Combine(Path.GetTempPath(),"umh-bridge-import-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{using var repo=new HubRepository(Path.Combine(root,"hub.db"));repo.Initialize();var runner=new FixtureRunner(async(request,emit,_ct)=>{Assert.Equal("importBridge",request.Operation);Assert.True(request.BridgePayload.HasValue);await emit(new(){Type="item",Item=new(){Platform="douyin",ContentId="1",SourceUrl="https://www.douyin.com/video/1",MediaResolved=false}});await emit(new(){Type="complete",Status="completed",Completeness="partial",ReasonCode="bridge_snapshot"});});await using var hub=new HubCoordinator(repo,runner,new(){DataRoot=root,DownloadRoot=root});hub.Enable();var payload=BridgePayload.Parse(Payload());var source=BridgeImports.Source(payload,"different-bound-account");var job=repo.CreateJob(source,root);await hub.ImportBridgeAsync(job.Id,payload.Value);Assert.Single(repo.ListItems(job.Id));Assert.Equal("bridge_account_mismatch",repo.GetJob(job.Id)!.ReasonCode);Assert.Equal("needs_action",repo.GetJob(job.Id)!.Status);Assert.Equal("partial",repo.GetJob(job.Id)!.Completeness);await Assert.ThrowsAsync<InvalidOperationException>(async()=>await hub.Submit(job.Id,"download"));repo.ConfirmBridge(job.Id);Assert.True(repo.GetJob(job.Id)!.Source.Bridge!.Confirmed);Assert.Equal("Synthetic viewer",repo.GetJob(job.Id)!.Source.Bridge!.ViewerName);Assert.Null(repo.GetJob(job.Id)!.Source.AccountId);}finally{Directory.Delete(root,true);}}
 [Fact]public void OpenedFolderCarriesItsNameOnlyForTheFolderKind(){const string body="""{"bridgeVersion":"1","platform":"douyin","listKind":"saved_folder","page":{"path":"/user/self","tab":"favorite_folder"},"folder":{"title":" 板鞋 ","id":"7300000000000000001"},"items":[{"hrefId":"123","oversized":true}]}""";var payload=BridgePayload.Parse(Encoding.UTF8.GetBytes(body));Assert.Equal("saved_folder",payload.ListKind);Assert.Equal("板鞋",payload.FolderTitle);Assert.Equal("板鞋",BridgeImports.Source(payload,null).Bridge!.FolderTitle);Assert.Null(BridgePayload.Parse(Encoding.UTF8.GetBytes(body.Replace(",\"folder\":{\"title\":\" 板鞋 \",\"id\":\"7300000000000000001\"}",""))).FolderTitle);foreach(var bad in new[]{body.Replace("\"saved_folder\"","\"liked\"").Replace("favorite_folder","like"),body.Replace("favorite_folder","favorite_collection"),body.Replace("\" 板鞋 \"","\"  \""),body.Replace("7300000000000000001","../x"),body.Replace("\"id\":","\"extra\":")})Assert.Throws<InvalidDataException>(()=>BridgePayload.Parse(Encoding.UTF8.GetBytes(bad)));}
}
